public void putInt(final int offset, final int value) {
		val address = virtualAddress + PAYLOAD_OFFSET;
		if (DEBUG >= LOG_TRACE) {
			log.trace("Writing payload int @ 0x{} + {}.", leftPad(virtualAddress), offset);
		}
		mmanager.putInt(address + offset, value);
	}
